interface Controllable {
    fun enable()
    fun disable()
}

interface Reportable {
    fun report(): String
}

class SmartMotor(val name: String) : Controllable, Reportable {
    var isRunning = false

    override fun enable() {
        isRunning = true
    }

    override fun disable() {
        isRunning = false
    }

    override fun report(): String {
        return if (isRunning) "$name: running" else "$name: stopped"
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testReportWhenStopped() {
        val motor = SmartMotor("Left Drive")
        Assert.assertEquals("Left Drive: stopped", motor.report())
    }

    @Test
    fun testReportWhenRunning() {
        val motor = SmartMotor("Left Drive")
        motor.enable()
        Assert.assertEquals("Left Drive: running", motor.report())
    }

    @Test
    fun testIsControllable() {
        val motor = SmartMotor("Test")
        Assert.assertTrue(motor is Controllable)
    }

    @Test
    fun testIsReportable() {
        val motor = SmartMotor("Test")
        Assert.assertTrue(motor is Reportable)
    }

    @Test
    fun testEnableDisable() {
        val motor = SmartMotor("Arm")
        motor.enable()
        Assert.assertTrue(motor.isRunning)
        motor.disable()
        Assert.assertFalse(motor.isRunning)
    }
}
